int listen_fd; // Socket FD created via socket() & listen()

// Storage for remote client address information
struct sockaddr_storage client_addr;
socklen_t addr_len = sizeof(client_addr);

// Extracts the first pending connection request
// Returns new connected socket file descriptor
int conn_fd = accept(listen_fd,
                     (struct sockaddr *)&client_addr,
                     &addr_len);

// conn_fd is the new file descriptor for communication
if (conn_fd < 0) {
    // Error handling (e.g., EAGAIN, EINTR)
}
